import json
from jsonschema import Draft7Validator

def convert_structure(item):
  is_js_proxy = hasattr(item, '__class__') and item.__class__.__name__ == 'JsProxy'

  if is_js_proxy:
    if hasattr(item, 'to_py'):
      return convert_structure(item.to_py())
    else:
      try: return dict(item) # Jika JsProxy merepresentasikan objek JS
      except: pass
      try: return list(item)  # Jika JsProxy merepresentasikan array JS
      except: pass
      try: return str(item)   # Konversi paksa ke string sebagai fallback
      except: return None    # Atau kembalikan None jika tidak bisa dikonversi
  elif isinstance(item, dict):
      # Jika dictionary, proses setiap value secara rekursif
      return {k: convert_structure(v) for k, v in item.items()}
  elif isinstance(item, list):
      # Jika list, proses setiap elemen secara rekursif
      return [convert_structure(elem) for elem in item]
  else:
      # Jika tipe dasar yang sudah kompatibel (str, int, float, bool, None), kembalikan apa adanya
      return item

new_converted = convert_structure(new)


